-- Additive P1 hardening for MAT-FUNC-034/035/047/062.
-- Economic outcomes require authoritative source events, independent AAL2 review and immutable evidence.

create table public.reward_source_events(
 id uuid primary key default extensions.gen_random_uuid(),
 organization_id uuid not null references public.organizations(id)on delete restrict,
 event_type text not null check(event_type~'^[A-Z][A-Z0-9_.]{2,79}$'),
 audience_type text not null check(audience_type in('CLIENT_ORGANIZATION','REFERRED_CLIENT','REFERRED_PROVIDER')),
 source_reference_type text not null check(source_reference_type~'^[A-Z][A-Z0-9_]{2,63}$'),
 source_reference_id text not null check(length(btrim(source_reference_id))between 3 and 200),
 eligibility_snapshot jsonb not null check(jsonb_typeof(eligibility_snapshot)='object'),
 evidence_refs jsonb not null check(jsonb_typeof(evidence_refs)='array'and jsonb_array_length(evidence_refs)>0),
 evidence_hash text not null check(evidence_hash~'^[0-9a-f]{64}$'),
 occurred_at timestamptz not null,
 recorded_by uuid not null references auth.users(id),
 correlation_id uuid not null,
 recorded_at timestamptz not null default clock_timestamp(),
 unique(organization_id,event_type,source_reference_type,source_reference_id),unique(id,organization_id)
);
create index reward_source_events_org_idx on public.reward_source_events(organization_id,event_type,occurred_at desc);

create table public.reward_award_approvals(
 id uuid primary key default extensions.gen_random_uuid(),
 organization_id uuid not null,
 source_event_id uuid not null,
 rule_version_id uuid not null references public.reward_rule_versions(id)on delete restrict,
 decision text not null check(decision in('APPROVED','REJECTED')),
 rationale text not null check(length(btrim(rationale))between 10 and 1000),
 decided_by uuid not null references auth.users(id),
 correlation_id uuid not null,
 decided_at timestamptz not null default clock_timestamp(),
 foreign key(source_event_id,organization_id)references public.reward_source_events(id,organization_id)on delete restrict,
 unique(source_event_id,rule_version_id),unique(id,organization_id)
);
create index reward_award_approvals_org_idx on public.reward_award_approvals(organization_id,decision,decided_at desc);

create table public.measurement_baseline_submissions(
 id uuid primary key default extensions.gen_random_uuid(),
 organization_id uuid not null references public.organizations(id)on delete restrict,
 subject_type text not null check(subject_type in('RECOMMENDATION','OPPORTUNITY','SERVICE','PROJECT','CONTRACT','ORGANIZATION')),
 subject_id uuid not null,
 metric_code text not null check(metric_code~'^[A-Z][A-Z0-9_]{2,63}$'),
 baseline_amount_minor bigint not null check(baseline_amount_minor>=0),
 currency char(3)not null check(currency~'^[A-Z]{3}$'),
 period_start date not null,
 period_end date not null,
 source_type text not null check(source_type in('INVOICE','CONTRACT','ACCOUNTING_EXPORT','METER_READING','SIGNED_REPORT','AUDITED_IMPORT')),
 source_reference text not null check(length(btrim(source_reference))between 3 and 240),
 evidence_refs jsonb not null check(jsonb_typeof(evidence_refs)='array'and jsonb_array_length(evidence_refs)>0),
 evidence_hash text not null check(evidence_hash~'^[0-9a-f]{64}$'),
 methodology_version text not null check(methodology_version~'^[A-Z0-9][A-Z0-9._-]{2,79}$'),
 status text not null default'DRAFT'check(status='DRAFT'),
 submitted_by uuid not null references auth.users(id),
 correlation_id uuid not null,
 submitted_at timestamptz not null default clock_timestamp(),
 unique(organization_id,subject_type,subject_id,metric_code,evidence_hash),unique(id,organization_id),
 check(period_end>=period_start)
);
create index baseline_submissions_review_idx on public.measurement_baseline_submissions(organization_id,submitted_at desc);

create table public.measurement_baseline_verification_decisions(
 id uuid primary key default extensions.gen_random_uuid(),
 submission_id uuid not null unique references public.measurement_baseline_submissions(id)on delete restrict,
 organization_id uuid not null,
 baseline_id uuid,
 decision text not null check(decision in('APPROVED','REJECTED')),
 rationale text not null check(length(btrim(rationale))between 10 and 1000),
 decided_by uuid not null references auth.users(id),
 correlation_id uuid not null,
 decided_at timestamptz not null default clock_timestamp(),
 foreign key(submission_id,organization_id)references public.measurement_baseline_submissions(id,organization_id)on delete restrict,
 foreign key(baseline_id,organization_id)references public.measurement_baselines(id,organization_id)on delete restrict,
 check((decision='APPROVED')=(baseline_id is not null))
);
create index baseline_verification_decisions_org_idx on public.measurement_baseline_verification_decisions(organization_id,decision,decided_at desc);

do $$declare t text;begin foreach t in array array['reward_source_events','reward_award_approvals','measurement_baseline_submissions','measurement_baseline_verification_decisions']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);end loop;end$$;
create trigger reward_source_events_immutable before update or delete on public.reward_source_events for each row execute function private.prevent_update_delete();
create trigger reward_award_approvals_immutable before update or delete on public.reward_award_approvals for each row execute function private.prevent_update_delete();
create trigger baseline_submissions_immutable before update or delete on public.measurement_baseline_submissions for each row execute function private.prevent_update_delete();
create trigger baseline_verification_decisions_immutable before update or delete on public.measurement_baseline_verification_decisions for each row execute function private.prevent_update_delete();

create function private.rewards_sensitive_aal2(p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select p_actor is not null and p_actor=auth.uid()and coalesce(auth.jwt()->>'aal','')='aal2'and private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','FINANCE_MANAGER','COMPLIANCE_MANAGER'],p_actor)$$;
revoke all on function private.rewards_sensitive_aal2(uuid)from public,anon,authenticated,service_role;

create function private.assert_baseline_subject_scope(p_organization_id uuid,p_subject_type text,p_subject_id uuid)returns void language plpgsql security definer set search_path=pg_catalog,public as $$declare v_valid boolean;begin
 select case p_subject_type
  when'RECOMMENDATION'then exists(select 1 from public.diagnostic_recommendations x where x.id=p_subject_id and x.organization_id=p_organization_id)
  when'OPPORTUNITY'then exists(select 1 from public.diagnostic_opportunities x where x.id=p_subject_id and x.organization_id=p_organization_id)
  when'SERVICE'then exists(select 1 from public.catalog_services x where x.id=p_subject_id)
  when'PROJECT'then exists(select 1 from public.client_projects x where x.id=p_subject_id and x.organization_id=p_organization_id)
  when'CONTRACT'then exists(select 1 from public.contracts x where x.id=p_subject_id and x.client_organization_id=p_organization_id)
  when'ORGANIZATION'then p_subject_id=p_organization_id and exists(select 1 from public.organizations x where x.id=p_organization_id and x.status='ACTIVE')
  else false end into v_valid;
 if not coalesce(v_valid,false)then raise exception'BASELINE_SUBJECT_SCOPE_DENIED'using errcode='42501';end if;
end$$;
revoke all on function private.assert_baseline_subject_scope(uuid,text,uuid)from public,anon,authenticated,service_role;

create function public.record_reward_source_event(p_organization_id uuid,p_event_type text,p_audience_type text,p_source_reference_type text,p_source_reference_id text,p_eligibility_snapshot jsonb,p_evidence_refs jsonb,p_evidence_hash text,p_occurred_at timestamptz,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();c public.referral_conversions%rowtype;h text;cached jsonb;x uuid;r jsonb;begin
 if not private.rewards_sensitive_aal2(a)then raise exception'REWARD_SOURCE_EVENT_AAL2_REQUIRED'using errcode='42501';end if;if p_event_type!~'^[A-Z][A-Z0-9_.]{2,79}$'or p_audience_type not in('CLIENT_ORGANIZATION','REFERRED_CLIENT','REFERRED_PROVIDER')or p_source_reference_type!~'^[A-Z][A-Z0-9_]{2,63}$'or length(btrim(coalesce(p_source_reference_id,'')))not between 3 and 200 or jsonb_typeof(p_eligibility_snapshot)<>'object'or jsonb_typeof(p_evidence_refs)<>'array'or jsonb_array_length(p_evidence_refs)=0 or p_evidence_hash!~'^[0-9a-f]{64}$'or p_occurred_at>clock_timestamp()then raise exception'INVALID_REWARD_SOURCE_EVENT'using errcode='22023';end if;
 if p_audience_type in('REFERRED_CLIENT','REFERRED_PROVIDER')then if p_source_reference_type<>'REFERRAL_CONVERSION'or p_source_reference_id!~'^[0-9a-f-]{36}$'then raise exception'REWARD_REFERRAL_SOURCE_REQUIRED'using errcode='22023';end if;select*into c from public.referral_conversions where id=p_source_reference_id::uuid and target_organization_id=p_organization_id and conversion_stage in('VERIFIED','ACTIVE');if not found then raise exception'VERIFIED_REFERRAL_SOURCE_REQUIRED'using errcode='23514';end if;if p_event_type<>'REFERRAL_VERIFIED'or(p_audience_type='REFERRED_PROVIDER'and not exists(select 1 from public.provider_profiles q where q.provider_organization_id=p_organization_id and q.company_status='VERIFIED'))or(p_audience_type='REFERRED_CLIENT'and not exists(select 1 from public.client_compliance_cases q where q.organization_id=p_organization_id and q.status='VERIFIED'))then raise exception'REWARD_AUDIENCE_SOURCE_MISMATCH'using errcode='23514';end if;end if;
 h:=private.canonical_request_hash(jsonb_build_object('org',p_organization_id,'event',p_event_type,'audience',p_audience_type,'source_type',p_source_reference_type,'source_id',p_source_reference_id,'eligibility',p_eligibility_snapshot,'evidence',p_evidence_refs,'evidence_hash',p_evidence_hash,'occurred_at',p_occurred_at));cached:=private.begin_rewards_command(p_organization_id,a,'reward.source_event.record',p_idempotency_key,h);if cached is not null then return cached;end if;insert into public.reward_source_events(organization_id,event_type,audience_type,source_reference_type,source_reference_id,eligibility_snapshot,evidence_refs,evidence_hash,occurred_at,recorded_by,correlation_id)values(p_organization_id,p_event_type,p_audience_type,p_source_reference_type,p_source_reference_id,p_eligibility_snapshot,p_evidence_refs,p_evidence_hash,p_occurred_at,a,p_correlation_id)returning id into x;
 r:=jsonb_build_object('outcome','REWARD_SOURCE_EVENT_RECORDED','source_event_id',x);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','reward.source_event.recorded','reward_source_event',x::text,p_correlation_id,jsonb_build_object('event_type',p_event_type,'audience_type',p_audience_type,'source_reference_type',p_source_reference_type,'source_reference_id',p_source_reference_id),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'reward_source_event',x::text,'RewardSourceEventRecordedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_rewards_command(p_organization_id,'reward.source_event.record',p_idempotency_key,r);return r;end$$;

create function public.decide_reward_award(p_source_event_id uuid,p_rule_version_id uuid,p_decision text,p_rationale text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();e public.reward_source_events%rowtype;v public.reward_rule_versions%rowtype;h text;cached jsonb;x uuid;r jsonb;begin
 if not private.rewards_sensitive_aal2(a)then raise exception'REWARD_APPROVAL_AAL2_REQUIRED'using errcode='42501';end if;select*into e from public.reward_source_events where id=p_source_event_id;select*into v from public.reward_rule_versions where id=p_rule_version_id and status='ACTIVE'and effective_from<=clock_timestamp()and(effective_until is null or effective_until>clock_timestamp());if e.id is null or v.id is null then raise exception'REWARD_SOURCE_OR_RULE_NOT_FOUND'using errcode='P0002';end if;if a=e.recorded_by then raise exception'REWARD_DUAL_CONTROL_REQUIRED'using errcode='42501';end if;if p_decision not in('APPROVED','REJECTED')or length(btrim(coalesce(p_rationale,'')))not between 10 and 1000 or e.event_type<>v.trigger_event or e.audience_type<>v.audience_type or not(e.eligibility_snapshot@>v.eligibility_rule)then raise exception'REWARD_RULE_SOURCE_MISMATCH'using errcode='23514';end if;
 h:=private.canonical_request_hash(jsonb_build_object('source_event',e.id,'rule_version',v.id,'decision',p_decision,'rationale',p_rationale));cached:=private.begin_rewards_command(e.organization_id,a,'reward.award.decide',p_idempotency_key,h);if cached is not null then return cached;end if;insert into public.reward_award_approvals(organization_id,source_event_id,rule_version_id,decision,rationale,decided_by,correlation_id)values(e.organization_id,e.id,v.id,p_decision,p_rationale,a,p_correlation_id)returning id into x;
 r:=jsonb_build_object('outcome','REWARD_AWARD_'||p_decision,'approval_id',x,'source_event_id',e.id,'rule_version_id',v.id);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(e.organization_id,a,'USER','reward.award.'||lower(p_decision),'reward_award_approval',x::text,p_correlation_id,jsonb_build_object('source_event_id',e.id,'rule_version_id',v.id,'recorded_by',e.recorded_by),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(e.organization_id,'reward_award_approval',x::text,'RewardAward'||initcap(lower(p_decision))||'V1',p_correlation_id,r,p_idempotency_key);perform private.finish_rewards_command(e.organization_id,'reward.award.decide',p_idempotency_key,r);return r;end$$;

create or replace function public.award_reward(p_organization_id uuid,p_wallet_id uuid,p_rule_version_id uuid,p_trigger_reference_type text,p_trigger_reference_id text,p_anti_abuse_key_hash text,p_eligibility_evidence jsonb,p_approval_reference text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();v public.reward_rule_versions%rowtype;e public.reward_source_events%rowtype;ap public.reward_award_approvals%rowtype;recipient_total bigint;global_total bigint;last_at timestamptz;h text;cached jsonb;grant_id uuid;issued jsonb;r jsonb;child_key text;begin
 if not private.rewards_sensitive_aal2(a)then raise exception'REWARD_AWARD_AAL2_REQUIRED'using errcode='42501';end if;select*into v from public.reward_rule_versions where id=p_rule_version_id and status='ACTIVE'and effective_from<=clock_timestamp()and(effective_until is null or effective_until>clock_timestamp());if not found then raise exception'ACTIVE_REWARD_RULE_REQUIRED'using errcode='22023';end if;
 if jsonb_typeof(p_eligibility_evidence)<>'object'or(select array_agg(k order by k)from jsonb_object_keys(p_eligibility_evidence)k)<>array['source_event_id']::text[]or coalesce(p_eligibility_evidence->>'source_event_id','')!~'^[0-9a-f-]{36}$'or coalesce(p_approval_reference,'')!~'^[0-9a-f-]{36}$'or p_anti_abuse_key_hash!~'^[0-9a-f]{64}$'then raise exception'REWARD_AUTHORITY_EVIDENCE_REQUIRED'using errcode='22023';end if;select*into e from public.reward_source_events where id=(p_eligibility_evidence->>'source_event_id')::uuid and organization_id=p_organization_id;select*into ap from public.reward_award_approvals where id=p_approval_reference::uuid and organization_id=p_organization_id and source_event_id=e.id and rule_version_id=v.id and decision='APPROVED';if e.id is null or ap.id is null then raise exception'APPROVED_REWARD_SOURCE_REQUIRED'using errcode='23514';end if;
 if e.event_type<>v.trigger_event or e.audience_type<>v.audience_type or e.source_reference_type<>p_trigger_reference_type or e.source_reference_id<>p_trigger_reference_id or not(e.eligibility_snapshot@>v.eligibility_rule)or ap.decided_by=e.recorded_by then raise exception'REWARD_SOURCE_RULE_BINDING_FAILED'using errcode='23514';end if;perform 1 from public.credit_wallets where id=p_wallet_id and organization_id=p_organization_id and wallet_type='CLIENT'for update;if not found then raise exception'CLIENT_WALLET_NOT_FOUND'using errcode='P0002';end if;
 h:=private.canonical_request_hash(jsonb_build_object('organization',p_organization_id,'wallet',p_wallet_id,'rule_version',v.id,'source_event',e.id,'approval',ap.id,'anti_abuse_hash',p_anti_abuse_key_hash));cached:=private.begin_rewards_command(p_organization_id,a,'reward.award',p_idempotency_key,h);if cached is not null then return cached;end if;perform pg_advisory_xact_lock(hashtextextended('reward-award:'||v.rule_code,0));select coalesce(sum(g.quantity),0),max(g.granted_at)into recipient_total,last_at from public.reward_grants g where g.organization_id=p_organization_id and g.rule_code=v.rule_code and g.granted_at>=clock_timestamp()-make_interval(days=>v.window_days);select coalesce(sum(g.quantity),0)into global_total from public.reward_grants g where g.rule_code=v.rule_code and g.granted_at>=clock_timestamp()-make_interval(days=>v.window_days);if recipient_total+v.bonus_credits>v.per_recipient_cap_credits then raise exception'REWARD_RECIPIENT_CAP_EXCEEDED'using errcode='23514';end if;if global_total+v.bonus_credits>v.global_cap_credits then raise exception'REWARD_GLOBAL_CAP_EXCEEDED'using errcode='23514';end if;if last_at is not null and last_at+make_interval(hours=>v.cooldown_hours)>clock_timestamp()then raise exception'REWARD_COOLDOWN_ACTIVE'using errcode='23514';end if;
 child_key:='reward-credit-'||encode(extensions.digest(convert_to(p_idempotency_key,'UTF8'),'sha256'),'hex');issued:=public.issue_credits(p_organization_id,p_wallet_id,'BONUS',v.bonus_credits,clock_timestamp()+make_interval(days=>v.credit_validity_days),null,'REWARD_EVENT:'||e.id::text,0,v.rule_code||'-V'||v.version_number::text,ap.id::text,child_key,p_correlation_id);insert into public.reward_grants(organization_id,wallet_id,rule_version_id,rule_code,trigger_reference_type,trigger_reference_id,anti_abuse_key_hash,eligibility_evidence,quantity,credit_ledger_entry_id,credit_lot_id,approval_reference,correlation_id,idempotency_key,granted_by)values(p_organization_id,p_wallet_id,v.id,v.rule_code,e.source_reference_type,e.source_reference_id,p_anti_abuse_key_hash,jsonb_build_object('source_event_id',e.id,'source_evidence_hash',e.evidence_hash,'approval_id',ap.id),v.bonus_credits,(issued->>'entry_id')::bigint,(issued->>'credit_lot_id')::uuid,ap.id::text,p_correlation_id,p_idempotency_key,a)returning id into grant_id;
 r:=jsonb_build_object('outcome','REWARD_GRANTED','reward_grant_id',grant_id,'source_event_id',e.id,'approval_id',ap.id,'quantity',v.bonus_credits,'credit_lot_id',issued->'credit_lot_id');insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','reward.granted','reward_grant',grant_id::text,p_correlation_id,jsonb_build_object('rule_version_id',v.id,'source_event_id',e.id,'approval_id',ap.id,'quantity',v.bonus_credits),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'reward_grant',grant_id::text,'RewardGrantedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_rewards_command(p_organization_id,'reward.award',p_idempotency_key,r);return r;end$$;

create or replace function public.advance_referral_conversion(p_referral_conversion_id uuid,p_to_stage text,p_evidence_refs jsonb,p_evidence_hash text,p_expected_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();c public.referral_conversions%rowtype;expected text;verified_actor uuid;h text;cached jsonb;r jsonb;begin
 select*into c from public.referral_conversions where id=p_referral_conversion_id;if not found then raise exception'REFERRAL_CONVERSION_NOT_FOUND'using errcode='P0002';end if;expected:=case c.conversion_stage when'REGISTERED'then'PROFILE_STARTED'when'PROFILE_STARTED'then'VERIFIED'when'VERIFIED'then'ACTIVE'end;if p_to_stage is distinct from expected or p_expected_row_version<>c.row_version or jsonb_typeof(p_evidence_refs)<>'array'or jsonb_array_length(p_evidence_refs)=0 or p_evidence_hash!~'^[0-9a-f]{64}$'then raise exception'INVALID_REFERRAL_TRANSITION'using errcode='55000';end if;
 if p_to_stage='PROFILE_STARTED'then if not private.has_org_role(c.target_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN','PROVIDER_OWNER','PROVIDER_MANAGER'],a)then raise exception'REFERRAL_PROFILE_TARGET_REQUIRED'using errcode='42501';end if;else if not private.rewards_sensitive_aal2(a)then raise exception'REFERRAL_VERIFICATION_AAL2_REQUIRED'using errcode='42501';end if;if a=c.registered_by then raise exception'REFERRAL_DUAL_CONTROL_REQUIRED'using errcode='42501';end if;if not exists(select 1 from public.organizations o where o.id=c.target_organization_id and o.status='ACTIVE')or not(exists(select 1 from public.client_compliance_cases q where q.organization_id=c.target_organization_id and q.status='VERIFIED')or exists(select 1 from public.provider_profiles q where q.provider_organization_id=c.target_organization_id and q.company_status='VERIFIED'))then raise exception'AUTHORITATIVE_ORGANIZATION_VERIFICATION_REQUIRED'using errcode='23514';end if;if p_to_stage='ACTIVE'then select actor_user_id into verified_actor from public.referral_conversion_events where referral_conversion_id=c.id and to_stage='VERIFIED';if verified_actor is null or verified_actor=a then raise exception'REFERRAL_ACTIVATION_DUAL_CONTROL_REQUIRED'using errcode='42501';end if;end if;end if;
 h:=private.canonical_request_hash(jsonb_build_object('conversion',c.id,'from',c.conversion_stage,'to',p_to_stage,'evidence',p_evidence_refs,'evidence_hash',p_evidence_hash,'expected',p_expected_row_version));cached:=private.begin_rewards_command(c.target_organization_id,a,'referral.conversion.advance',p_idempotency_key,h);if cached is not null then return cached;end if;update public.referral_conversions set conversion_stage=p_to_stage,updated_at=clock_timestamp(),row_version=row_version+1 where id=c.id and row_version=p_expected_row_version;if not found then raise exception'STALE_REFERRAL_CONVERSION'using errcode='40001';end if;insert into public.referral_conversion_events(referral_conversion_id,source_organization_id,from_stage,to_stage,evidence_refs,evidence_hash,correlation_id,actor_user_id)values(c.id,c.source_organization_id,c.conversion_stage,p_to_stage,p_evidence_refs,p_evidence_hash,p_correlation_id,a);r:=jsonb_build_object('outcome','REFERRAL_STAGE_ADVANCED','referral_conversion_id',c.id,'conversion_stage',p_to_stage,'row_version',c.row_version+1);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(c.target_organization_id,a,'USER','referral.conversion.advanced','referral_conversion',c.id::text,p_correlation_id,jsonb_build_object('from_stage',c.conversion_stage,'to_stage',p_to_stage,'source_organization_id',c.source_organization_id,'evidence_hash',p_evidence_hash),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(c.target_organization_id,'referral_conversion',c.id::text,case when p_to_stage='VERIFIED'then'ReferralVerifiedV1'when p_to_stage='ACTIVE'then'ReferralActivatedV1'else'ReferralProfileStartedV1'end,p_correlation_id,r,p_idempotency_key);perform private.finish_rewards_command(c.target_organization_id,'referral.conversion.advance',p_idempotency_key,r);return r;end$$;

create or replace function public.capture_verified_baseline(p_organization_id uuid,p_subject_type text,p_subject_id uuid,p_metric_code text,p_baseline_amount_minor bigint,p_currency text,p_period_start date,p_period_end date,p_source_type text,p_source_reference text,p_evidence_refs jsonb,p_evidence_hash text,p_methodology_version text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();h text;cached jsonb;x uuid;r jsonb;begin
 if not private.has_org_role(p_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN','CLIENT_ACCOUNTING'],a)then raise exception'BASELINE_SUBMISSION_DENIED'using errcode='42501';end if;if p_subject_type not in('RECOMMENDATION','OPPORTUNITY','SERVICE','PROJECT','CONTRACT','ORGANIZATION')or p_metric_code!~'^[A-Z][A-Z0-9_]{2,63}$'or p_baseline_amount_minor<0 or p_currency!~'^[A-Z]{3}$'or p_period_end<p_period_start or p_source_type not in('INVOICE','CONTRACT','ACCOUNTING_EXPORT','METER_READING','SIGNED_REPORT','AUDITED_IMPORT')or length(btrim(coalesce(p_source_reference,'')))not between 3 and 240 or jsonb_typeof(p_evidence_refs)<>'array'or jsonb_array_length(p_evidence_refs)=0 or p_evidence_hash!~'^[0-9a-f]{64}$'or p_methodology_version!~'^[A-Z0-9][A-Z0-9._-]{2,79}$'then raise exception'VALID_BASELINE_SUBMISSION_REQUIRED'using errcode='22023';end if;perform private.assert_baseline_subject_scope(p_organization_id,p_subject_type,p_subject_id);
 h:=private.canonical_request_hash(jsonb_build_object('org',p_organization_id,'subject_type',p_subject_type,'subject_id',p_subject_id,'metric',p_metric_code,'amount_minor',p_baseline_amount_minor,'currency',p_currency,'period_start',p_period_start,'period_end',p_period_end,'source_type',p_source_type,'source_reference',p_source_reference,'evidence',p_evidence_refs,'evidence_hash',p_evidence_hash,'methodology',p_methodology_version));cached:=private.begin_rewards_command(p_organization_id,a,'measurement.baseline.capture',p_idempotency_key,h);if cached is not null then return cached;end if;insert into public.measurement_baseline_submissions(organization_id,subject_type,subject_id,metric_code,baseline_amount_minor,currency,period_start,period_end,source_type,source_reference,evidence_refs,evidence_hash,methodology_version,submitted_by,correlation_id)values(p_organization_id,p_subject_type,p_subject_id,p_metric_code,p_baseline_amount_minor,p_currency,p_period_start,p_period_end,p_source_type,p_source_reference,p_evidence_refs,p_evidence_hash,p_methodology_version,a,p_correlation_id)returning id into x;
 r:=jsonb_build_object('outcome','MEASUREMENT_BASELINE_DRAFT_SUBMITTED','baseline_submission_id',x,'verification_status','DRAFT');insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','measurement.baseline.submitted','measurement_baseline_submission',x::text,p_correlation_id,jsonb_build_object('subject_type',p_subject_type,'subject_id',p_subject_id,'metric_code',p_metric_code,'evidence_hash',p_evidence_hash),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'measurement_baseline_submission',x::text,'MeasurementBaselineSubmittedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_rewards_command(p_organization_id,'measurement.baseline.capture',p_idempotency_key,r);return r;end$$;

create function public.decide_measurement_baseline(p_submission_id uuid,p_decision text,p_rationale text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();s public.measurement_baseline_submissions%rowtype;n integer;h text;cached jsonb;b uuid;d uuid;r jsonb;begin
 if not private.rewards_sensitive_aal2(a)then raise exception'BASELINE_REVIEW_AAL2_REQUIRED'using errcode='42501';end if;select*into s from public.measurement_baseline_submissions where id=p_submission_id;if not found then raise exception'BASELINE_SUBMISSION_NOT_FOUND'using errcode='P0002';end if;if a=s.submitted_by then raise exception'BASELINE_DUAL_CONTROL_REQUIRED'using errcode='42501';end if;if p_decision not in('APPROVED','REJECTED')or length(btrim(coalesce(p_rationale,'')))not between 10 and 1000 then raise exception'INVALID_BASELINE_DECISION'using errcode='22023';end if;perform private.assert_baseline_subject_scope(s.organization_id,s.subject_type,s.subject_id);
 h:=private.canonical_request_hash(jsonb_build_object('submission',s.id,'decision',p_decision,'rationale',p_rationale));cached:=private.begin_rewards_command(s.organization_id,a,'measurement.baseline.decide',p_idempotency_key,h);if cached is not null then return cached;end if;perform pg_advisory_xact_lock(hashtextextended('baseline-review:'||s.id::text,0));if exists(select 1 from public.measurement_baseline_verification_decisions x where x.submission_id=s.id)then raise exception'BASELINE_ALREADY_DECIDED'using errcode='55000';end if;
 if p_decision='APPROVED'then perform pg_advisory_xact_lock(hashtextextended('baseline:'||s.organization_id::text||':'||s.subject_type||':'||s.subject_id::text||':'||s.metric_code,0));select coalesce(max(version_number),0)+1 into n from public.measurement_baselines where organization_id=s.organization_id and subject_type=s.subject_type and subject_id=s.subject_id and metric_code=s.metric_code;insert into public.measurement_baselines(organization_id,subject_type,subject_id,metric_code,version_number,baseline_amount_minor,currency,period_start,period_end,source_type,source_reference,evidence_refs,evidence_hash,methodology_version,verification_status,verified_by,correlation_id)values(s.organization_id,s.subject_type,s.subject_id,s.metric_code,n,s.baseline_amount_minor,s.currency,s.period_start,s.period_end,s.source_type,s.source_reference,s.evidence_refs,s.evidence_hash,s.methodology_version,'VERIFIED',a,p_correlation_id)returning id into b;end if;insert into public.measurement_baseline_verification_decisions(submission_id,organization_id,baseline_id,decision,rationale,decided_by,correlation_id)values(s.id,s.organization_id,b,p_decision,p_rationale,a,p_correlation_id)returning id into d;
 r:=jsonb_build_object('outcome','MEASUREMENT_BASELINE_'||p_decision,'baseline_submission_id',s.id,'baseline_id',b,'decision_id',d);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(s.organization_id,a,'USER','measurement.baseline.'||lower(p_decision),'measurement_baseline_decision',d::text,p_correlation_id,jsonb_build_object('submission_id',s.id,'baseline_id',b,'submitted_by',s.submitted_by,'evidence_hash',s.evidence_hash),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(s.organization_id,'measurement_baseline_submission',s.id::text,'MeasurementBaseline'||initcap(lower(p_decision))||'V1',p_correlation_id,r,p_idempotency_key);perform private.finish_rewards_command(s.organization_id,'measurement.baseline.decide',p_idempotency_key,r);return r;end$$;

create function private.guard_approved_baseline_measurement()returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$begin if not exists(select 1 from public.measurement_baseline_verification_decisions d where d.baseline_id=new.baseline_id and d.organization_id=new.organization_id and d.decision='APPROVED')then raise exception'INDEPENDENTLY_APPROVED_BASELINE_REQUIRED'using errcode='23514';end if;return new;end$$;
create trigger recommendation_roi_approved_baseline_guard before insert on public.recommendation_roi_snapshots for each row execute function private.guard_approved_baseline_measurement();
create trigger savings_approved_baseline_guard before insert on public.savings_measurements for each row execute function private.guard_approved_baseline_measurement();
revoke all on function private.guard_approved_baseline_measurement()from public,anon,authenticated,service_role;

create policy reward_source_events_tenant_read on public.reward_source_events for select to authenticated using(private.is_active_org_member(organization_id)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','FINANCE_MANAGER','COMPLIANCE_MANAGER','READ_ONLY_AUDITOR']));
create policy reward_award_approvals_tenant_read on public.reward_award_approvals for select to authenticated using(private.is_active_org_member(organization_id)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','FINANCE_MANAGER','COMPLIANCE_MANAGER','READ_ONLY_AUDITOR']));
create policy baseline_submissions_tenant_read on public.measurement_baseline_submissions for select to authenticated using(private.is_active_org_member(organization_id)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','FINANCE_MANAGER','READ_ONLY_AUDITOR']));
create policy baseline_decisions_tenant_read on public.measurement_baseline_verification_decisions for select to authenticated using(private.is_active_org_member(organization_id)or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','FINANCE_MANAGER','READ_ONLY_AUDITOR']));
grant select on public.reward_source_events,public.reward_award_approvals,public.measurement_baseline_submissions,public.measurement_baseline_verification_decisions to authenticated;

revoke all on function public.record_reward_source_event(uuid,text,text,text,text,jsonb,jsonb,text,timestamptz,text,uuid),public.decide_reward_award(uuid,uuid,text,text,text,uuid),public.decide_measurement_baseline(uuid,text,text,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.record_reward_source_event(uuid,text,text,text,text,jsonb,jsonb,text,timestamptz,text,uuid),public.decide_reward_award(uuid,uuid,text,text,text,uuid),public.decide_measurement_baseline(uuid,text,text,text,uuid)to authenticated;
revoke all on function public.award_reward(uuid,uuid,uuid,text,text,text,jsonb,text,text,uuid),public.advance_referral_conversion(uuid,text,jsonb,text,integer,text,uuid),public.capture_verified_baseline(uuid,text,uuid,text,bigint,text,date,date,text,text,jsonb,text,text,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.award_reward(uuid,uuid,uuid,text,text,text,jsonb,text,text,uuid),public.advance_referral_conversion(uuid,text,jsonb,text,integer,text,uuid),public.capture_verified_baseline(uuid,text,uuid,text,bigint,text,date,date,text,text,jsonb,text,text,text,uuid)to authenticated;
notify pgrst,'reload schema';
